CREATE TABLE tenants (id uuid PRIMARY KEY, name text NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE users (id uuid PRIMARY KEY, subject text UNIQUE NOT NULL);
CREATE TABLE memberships (tenant_id uuid REFERENCES tenants(id), user_id uuid REFERENCES users(id), role text NOT NULL CHECK(role IN ('admin','curator','artist','viewer')), PRIMARY KEY(tenant_id,user_id));
CREATE TABLE artists (tenant_id uuid REFERENCES tenants(id), id uuid, user_id uuid REFERENCES users(id), metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE artworks (tenant_id uuid REFERENCES tenants(id), id uuid, artist_id uuid NOT NULL, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,artist_id) REFERENCES artists(tenant_id,id));
CREATE TABLE artwork_revisions (tenant_id uuid, artwork_id uuid, revision integer CHECK(revision>0), snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,artwork_id,revision), FOREIGN KEY(tenant_id,artwork_id) REFERENCES artworks(tenant_id,id));
CREATE TABLE rights (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE assets (tenant_id uuid, id uuid, artwork_id uuid NOT NULL, rights_id uuid NOT NULL, object_key text NOT NULL, target_key text NOT NULL, sha256 text NOT NULL CHECK(sha256 ~ '^[0-9a-f]{64}$'), bytes bigint NOT NULL CHECK(bytes>0), mime text NOT NULL, scale_meters double precision NOT NULL CHECK(scale_meters>0 AND scale_meters<'Infinity'::float8), state text NOT NULL CHECK(state IN ('quarantine','stored')), revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,artwork_id) REFERENCES artworks(tenant_id,id), FOREIGN KEY(tenant_id,rights_id) REFERENCES rights(tenant_id,id));
CREATE TABLE exhibitions (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE exhibition_revisions (tenant_id uuid, exhibition_id uuid, revision integer CHECK(revision>0), snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,exhibition_id,revision), FOREIGN KEY(tenant_id,exhibition_id) REFERENCES exhibitions(tenant_id,id));
CREATE FUNCTION immutable_revision() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable revision'; END $$;
CREATE TRIGGER artwork_snapshot_immutable BEFORE UPDATE OR DELETE ON artwork_revisions FOR EACH ROW EXECUTE FUNCTION immutable_revision();
CREATE TRIGGER exhibition_snapshot_immutable BEFORE UPDATE OR DELETE ON exhibition_revisions FOR EACH ROW EXECUTE FUNCTION immutable_revision();
CREATE TABLE asset_derivatives (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE provenance_events (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE rooms (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE surfaces (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE openings (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE placements (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE lights (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE audio_zones (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE annotations (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE navigation_routes (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE scripts (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE publications (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE capture_jobs (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE backup_jobs (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE deployments (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE audit_events (tenant_id uuid REFERENCES tenants(id), id uuid, metadata jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,id));
-- Relations remain tenant-scoped; JSON metadata never substitutes for ownership links.
ALTER TABLE asset_derivatives ADD COLUMN asset_id uuid NOT NULL, ADD FOREIGN KEY(tenant_id,asset_id) REFERENCES assets(tenant_id,id);
ALTER TABLE provenance_events ADD COLUMN artwork_id uuid NOT NULL, ADD FOREIGN KEY(tenant_id,artwork_id) REFERENCES artworks(tenant_id,id);
ALTER TABLE rooms ADD COLUMN exhibition_id uuid NOT NULL, ADD FOREIGN KEY(tenant_id,exhibition_id) REFERENCES exhibitions(tenant_id,id);
ALTER TABLE surfaces ADD COLUMN room_id uuid NOT NULL, ADD FOREIGN KEY(tenant_id,room_id) REFERENCES rooms(tenant_id,id);
ALTER TABLE openings ADD COLUMN surface_id uuid NOT NULL, ADD FOREIGN KEY(tenant_id,surface_id) REFERENCES surfaces(tenant_id,id);
ALTER TABLE placements ADD COLUMN room_id uuid NOT NULL, ADD COLUMN artwork_id uuid NOT NULL, ADD FOREIGN KEY(tenant_id,room_id) REFERENCES rooms(tenant_id,id), ADD FOREIGN KEY(tenant_id,artwork_id) REFERENCES artworks(tenant_id,id);
ALTER TABLE lights ADD COLUMN room_id uuid NOT NULL, ADD FOREIGN KEY(tenant_id,room_id) REFERENCES rooms(tenant_id,id);
ALTER TABLE audio_zones ADD COLUMN room_id uuid NOT NULL, ADD FOREIGN KEY(tenant_id,room_id) REFERENCES rooms(tenant_id,id);
ALTER TABLE annotations ADD COLUMN exhibition_id uuid NOT NULL, ADD FOREIGN KEY(tenant_id,exhibition_id) REFERENCES exhibitions(tenant_id,id);
ALTER TABLE navigation_routes ADD COLUMN exhibition_id uuid NOT NULL, ADD FOREIGN KEY(tenant_id,exhibition_id) REFERENCES exhibitions(tenant_id,id);
ALTER TABLE scripts ADD COLUMN exhibition_id uuid NOT NULL, ADD FOREIGN KEY(tenant_id,exhibition_id) REFERENCES exhibitions(tenant_id,id);
ALTER TABLE publications ADD COLUMN exhibition_id uuid NOT NULL, ADD COLUMN exhibition_revision integer NOT NULL, ADD FOREIGN KEY(tenant_id,exhibition_id,exhibition_revision) REFERENCES exhibition_revisions(tenant_id,exhibition_id,revision);
